import java.util.*;class LruCache<K,V> extends LinkedHashMap<K,V>{private final int capacity;LruCache(int capacity){super(capacity,0.75f,true);this.capacity=capacity;}protected boolean removeEldestEntry(Map.Entry<K,V> eldest){return size()>capacity;}}class Main{public static void main(String[] args){LruCache<Integer,String> cache=new LruCache<>(2);cache.put(1,"A");cache.put(2,"B");cache.get(1);cache.put(3,"C");System.out.println(cache);}}
